      this.sendTo(session, key, "Sync", message((e) => writeSyncStep2(e, doc, body)));
      return;
    }
    Y.applyUpdate(doc, body, session);
    for (const other of this.sessions) {
      if (other !== session && this.subscribed(other, key)) {
        this.sendTo(other, key, "Sync", message((e) => writeUpdate(e, body)));
      }
    }
  }
}

